const repo = "acme/cli";
const label = "needs-triage";
const candidates: any[] = [];
const skipped: any[] = [];
let page = 1;

while (true) {
  const res: any = await tools.list_issues({ repo, state: "open", page });
  const items: any[] = Array.isArray(res)
    ? res
    : Array.isArray(res?.items)
      ? res.items
      : Array.isArray(res?.issues)
        ? res.issues
        : [];
  if (items.length === 0) break;

  for (const it of items) {
    const isPR = !!(it.pull_request || it.is_pull_request || it.pull_request_url);
    const labels = it.labels ?? [];
    const hasNoLabels = Array.isArray(labels) && labels.length === 0;
    const isOpen = (it.state ?? "open") === "open";
    if (isPR) {
      skipped.push({ number: it.number, reason: "pull request" });
      continue;
    }
    if (!isOpen) continue;
    if (hasNoLabels) {
      candidates.push(it.number);
    }
  }

  if (items.length < 50) break;
  page++;
  if (page > 100) break;
}

const uniq = [...new Set(candidates)];
const results: any[] = [];
for (const number of uniq) {
  try {
    await tools.add_label({ repo, number, label });
    results.push({ number, ok: true });
  } catch (e: any) {
    results.push({ number, ok: false, error: String(e?.message ?? e) });
  }
}

return { candidates: uniq, skipped, results };
