const repo = "acme/cli";
const seen = new Map<number, any>();
const pageSummaries: any[] = [];
let page = 1;

while (page <= 100) {
  const res: any = await tools.list_issues({ repo, state: "open", page });
  const items: any[] = Array.isArray(res)
    ? res
    : Array.isArray(res?.items)
      ? res.items
      : Array.isArray(res?.issues)
        ? res.issues
        : [];
  let newCount = 0;
  for (const it of items) {
    if (!seen.has(it.number)) {
      seen.set(it.number, it);
      newCount++;
    }
  }
  pageSummaries.push({ page, count: items.length, newCount });
  if (items.length === 0 || newCount === 0) break;
  page++;
}

const emptyLabel: any[] = [];
const noLabelsField: any[] = [];
const prs: any[] = [];
for (const [number, it] of seen) {
  if (it.pull_request || it.is_pull_request || it.pull_request_url) {
    prs.push(number);
    continue;
  }
  if (!Object.prototype.hasOwnProperty.call(it, "labels")) {
    noLabelsField.push(number);
    continue;
  }
  if (Array.isArray(it.labels) && it.labels.length === 0) {
    emptyLabel.push(number);
  }
}

return {
  totalOpenSeen: seen.size,
  pageSummaries,
  prs,
  noLabelsField,
  emptyLabel: emptyLabel.sort((a, b) => b - a),
};
